// Same gate as the send webhook, same constant-time comparison, same rule
// about never echoing either value into a retained execution.
const crypto = require('crypto');
const req = $input.first().json;
const given = String((req.headers || {})['x-ryvo-cockpit-secret'] || '');
const want  = String($env.COCKPIT_SEND_SECRET || '');
let authed = false;
if (want && given.length === want.length) {
  authed = crypto.timingSafeEqual(Buffer.from(given), Buffer.from(want));
}
const body = req.body || {};
return [{ json: { authed, calendarId: String(body.calendarId || '').trim(), timezone: String(body.timezone || 'Europe/Lisbon') } }];

// THE WHOLE POINT OF THIS ENDPOINT.
//
// Google's free/busy returns HTTP 200 with an empty busy list for a calendar
// it cannot read. A wrong id is therefore byte-identical to a completely free
// calendar, and a Concierge trusting it would offer every slot in the window
// as available. That was caught before it shipped by probing with a bad id on
// purpose; this is the same check, run at onboarding instead of at runtime.
//
// So "valid" requires all three, not just the status:
//   1. a 2xx
//   2. the calendar KEY present in calendars
//   3. no errors array on it
const a = $('CheckSecret').first().json;
const res = $input.first().json;
const body = res.body || {};
const cal = (body.calendars || {})[a.calendarId];

let ok = false, error = null, busyCount = null;

if (res.statusCode < 200 || res.statusCode >= 300) {
  error = 'google_http_' + res.statusCode + (body.error && body.error.message ? ':' + body.error.message : '');
} else if (!cal) {
  error = 'calendar_absent_from_response';
} else if (Array.isArray(cal.errors) && cal.errors.length) {
  error = 'calendar_error:' + cal.errors.map(e => e.reason).join(',');
} else {
  ok = true;
  busyCount = Array.isArray(cal.busy) ? cal.busy.length : 0;
}

return [{ json: { ok, error, busyCount, calendarId: a.calendarId } }];
